local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["bb01e1bb956b0aa4"] = { "La battaglia per il ⟦Arathi Basin=Bacino d'Arathi⟧ comincerà tra 1 minuto.", "." },
  ["bb058726a9c6103d"] = { "%s prende la mira...", "." },
  ["bb09250787d5bc2c"] = { "Dopo questa faremo nuove tacche sulle nostre asce.", "." },
  ["bb0e3acdda247f6c"] = { "Mist! Temevo che non ti avrei mai più rivisto! Sì, sto bene, non preoccuparti per me. Devi riposare e recuperare le forze.", "." },
  ["bb0ee22b6f312a2f"] = { "La tua volontà non è abbastanza forte da manipolare le forze che controlliamo, {class}.", "." },
  ["bb1ae0812f6640ac"] = { "Venite, piccoletti. Affrontatemi!", "." },
  ["bb1ea928ca3e8ff2"] = { "Le stalle sono di nuovo piene! La nostra cavalleria presto cavalcherà!", "." },
  ["bb349076981a8996"] = { "Il ⟦Temple of the Moon=Tempio della Luna⟧ è la casa dei sacerdoti di Elune. Lì troverai Jandria e Lariia, che ti guideranno ancora sulla via del sacerdozio.", "." },
  ["bb5a08d1318dc40f"] = { "C'è una cassetta della posta in posizione comodissima, proprio tra la banca di ⟦Stormwind=Roccavento⟧ e la locanda Gilded Rose, nel ⟦Trade District=Quartiere del Commercio⟧.", "." },
  ["bb5a9e9d3f034705"] = { "<Il gran inquisitore Fierasponda scuote la testa.>\n\nNo... Rimase in disparte a guardare mentre la legione di non morti si abbatteva su di noi. Poco dopo, i miei poteri si esaurirono. Fui il primo a cadere... Di certo mi avrebbero fatto a pezzi mentre giacevo lì privo di sensi; invece mi ignorarono del tutto, concentrando tutta la loro attenzione sul gran signore.", "." },
  ["bb5b66e082f8144f"] = { "%s vede morire il sorvegliante e fugge in preda al terrore!", "." },
  ["bb5df2ec8c311e58"] = { "Qui al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ non abbiamo un istruttore di Alchimia, ma ce n'è uno a ⟦Thunder Bluff=Picco del Tuono⟧, a nord. Segui la strada fin lì e, quando arrivi in cima, chiedi indicazioni a uno dei Guardiani del Picco.", "." },
  ["bb5e799d47b2356c"] = { "Sono tutti fucili e fiamme finché qualcuno non perde e ci lascia le penne.", "." },
  ["bb6e74a31d684cf7"] = { "Gli spiriti mi avevano detto che saresti <venuto/venuta>, che mi avresti cercato per un motivo, ma che forse nemmeno tu lo conosci. Allora, sai perché sei qui?", "." },
  ["bb6eff6febb2d44d"] = { "Ehi, questo mi ricorda che devo far riparare i miei stivali a razzo. Un consiglio da amico: stivali a razzo e grifoni non vanno d'accordo.\n\nOh, ma a te servono indicazioni... vai pure al Distretto dei Nani, troverai ⟦Lilliam Sparkspindle=Lilliam Saldafresa⟧ verso il fondo.", "." },
  ["bb7dae267f2e756c"] = { "È passato tanto tempo, Bethor, amico mio.", "." },
  ["bb879cb033020796"] = { "Preparati all'impatto glorioso, Impsy!", "." },
  ["bba42aa824e4054b"] = { "No, non che io sappia. Sembra dipendere soprattutto dalla regione. Alcune razze le chiamano poltiglie, altre melme. Per lo più è questione di preferenza.\n\nOgni volta che ho incontrato melme, fanghiglie o poltiglie, erano in pratica le stesse creature. Le differenze sembrano dipendere dal loro ambiente, ed è per questo che ci serve un campione puro.", "." },
  ["bbb388a11c4b9e9c"] = { "Ah, cerchi Lucan Cordell. Ha una bottega ai margini del ⟦Magic Quarter=Quartiere della Magia⟧, sulla strada per le ⟦Stockade=Segrete di Roccavento⟧.", "." },
  ["bbb66c90368769b4"] = { "<Bentornato/Bentornata>, {name}. Hai dimostrato il tuo valore al nostro fianco contro Ragnaros e la tua presenza tra noi è sempre gradita.", "." },
  ["bbb94fd2c760ed17"] = { "I nani ⟦Dark Iron=Ferroscuro⟧ della Fossa delle Scorie, nella ⟦Searing Gorge=Gorgia Rovente⟧, hanno moltissime scatole chiuse a chiave.", "." },
  ["bbbf58e50b6d2057"] = { "Ti presenti per il servizio, {class}? Tutto il materiale bellico sia dell'⟦Horde=Orda⟧ sia dell'⟦Alliance=Alleanza⟧ è pronto e viene spedito a ⟦Silithus=Silitus⟧ proprio ora. Dovrebbe arrivare tutto in meno di un giorno. Spero che qualcuno abbia trovato i vari pezzi dello Scettro delle Sabbie Mutevoli e li abbia rimessi insieme.", "." },
  ["bbc6bc0f21103b74"] = { "Il magnete per spettri attira %s...", "." },
  ["bbc9a7a7f1219fe0"] = { "Chi controlla il Dun Baldar South Bunker?", "." },
  ["bbcefed8fa5e8bc6"] = { "Il trasmogrificatore", "." },
  ["bbd6059af83f376d"] = { "In tempi difficili un druido può essere un caro amico per chi gli sta intorno. Chiedi a uno qualunque dei druidi nell'⟦Cenarion Enclave=Enclave Cenariana⟧ e ti dirà lo stesso.", "." },
  ["bbf52fbc4c8626fe"] = { "Mi serve una mano qui. {name} mi ha visto.", "." },
  ["bbf8281a2bddfa7e"] = { "Ciuf ciuf, tuu tuu! Buona Veglia delle Ombre, {name}!", "." },
  ["bbf836df93d60425"] = { "Fu durante la Separazione degli Elementi che il Signore del Fuoco, Ragnaros, cercò di divorare il mio signore, Thunderaan, Principe dell'Aria.\n\n<Demitrian china il capo, il volto contratto dalla rabbia.>\n\nPronuncia il suo nome e decorerò questo campo devastato con le tue viscere. Taci e ascolta.", "." },
  ["bbfb06d6fdbc81f1"] = { "A Charog piace spendere i suoi soldi al Busted Drum. Andiamo a fargli visita, {name}.", "." },
})
